    // Voorwoord
    'voorwoord.title': 'Voorwoord',
    'voorwoord.subtitle': 'Waarom dit boek?',
    'voorwoord.p1': "Al meer dan vijfentwintig jaar doe ik opzoekingen naar onze voorouders. Op zondag 29 september 2024 kwamen we samen in het Prullenbos in Laarne: honderdtwaalf afstammelingen van Marcel Deforce en Magdalena Geldof. Die dag maakte één ding duidelijk: het was tijd om al mijn ontdekkingen samen te brengen in leesbare verhalen die de feiten tot leven brengen.",
    'voorwoord.p2': "Dit boek vertelt de reis van de families Deleforge en Follet, die rond 1685 in Frans Waals-Vlaanderen leefden, via hun migratie naar West-Vlaanderen, tot aan hun vestiging in Izegem. Centraal staat Charles-Louis Deforce, mijn overgrootvader – de schakel tussen de verre voorouders en de generaties die wij nog gekend hebben.",
    'voorwoord.p3': "Ik hoop dat dit boek jullie verbindt met het verleden en misschien de aanzet geeft tot een eigen zoektocht. Dit is mijn bijdrage aan onze familiegeschiedenis. Nu is het aan jullie om ze verder te schrijven.",
    'voorwoord.p4': "Dit boek is geen volledige familiegeschiedenis. Zo'n project zou jaren vergen, en misschien wel onmogelijk zijn. Het is een verzameling verhalen – verhalen over de mensen die ons voorafgingen, over hun leven, hun keuzes, hun worstelingen en hun kleine overwinningen.",
    'voorwoord.p5': "Sommige van deze verhalen zijn goed gedocumenteerd; andere berusten op fragmenten, op interpretaties, op verbanden die ik zelf heb gelegd. Waar ik twijfel, vermeld ik dat. Waar ik zekerheid heb, verwijs ik naar de bronnen.",
    'voorwoord.p6': "De stamboom is een levend document. Elke generatie voegt er iets aan toe. Elke ontdekking opent nieuwe vragen. En elke vraag leidt – als we geluk hebben – naar een nieuw verhaal.",
    'voorwoord.p7': "In de eerste hoofdstukken ga ik terug naar de vroegste voorouders die ik kon traceren: de families Deleforge en Follet, die rond 1685 in het Franse Waals-Vlaanderen leefden.",
    'voorwoord.p8': "Daarna volg ik de lijn door de eeuwen heen: van de stamouders Hubert en Antoinette naar hun kinderen en kleinkinderen, van de migratie naar West-Vlaanderen naar de vestiging in Izegem.",
    'voorwoord.p9': "Eén figuur staat centraal in dit verhaal: Charles-Louis Deforce, mijn overgrootvader. Over hem werd in de familie nauwelijks gesproken, maar zijn sporen liggen overal: in de registers, in de foto's, in de verhalen die wél werden doorverteld.",
    'voorwoord.quote': '"Het is aan de komende generaties om verder te zoeken: nieuwe gegevens toe te voegen, bronnen op te diepen, verbanden scherper te trekken. Dit is geen eindpunt, maar een startpunt voor verdere ontdekkingen."',
    'voorwoord.p10': "Ik hoop dat dit boek jullie iets geeft: een gevoel van verbondenheid met het verleden, een beter begrip van waar we vandaan komen, en misschien – wie weet – de aanzet tot een eigen zoektocht.",
    'voorwoord.p11': "Dit is mijn bijdrage aan die geschiedenis. Nu is het aan jullie om ze verder te schrijven.",
