    'game.tt.wedding.character': 'Hubert & Antoinette',
    'game.tt.wedding.choice1': 'Bestudeer het huwelijkscontract',
    'game.tt.wedding.choice2': 'Neem deel aan de feestelijkheden',

    'game.tt.forest.title': 'Het Bois d\'Haubourdin',
    'game.tt.forest.desc': 'In het dichte bos werken de boquillons al generaties lang. Je vader leert je de geheimen van het hout: welke bomen het beste branden, hoe je houtskool maakt.',
    'game.tt.forest.location': 'Bois d\'Haubourdin',
    'game.tt.forest.character': 'De Boquillons',
    'game.tt.forest.choice1': 'Leer het ambacht van je vader',
    'game.tt.forest.choice2': 'Keer terug voor de huwelijksvoorbereidingen',

    'game.tt.contract.title': 'Het Huwelijkscontract',
    'game.tt.contract.desc': 'De notaris leest het contract voor: Hubert brengt landbouwwerktuigen en gereedschap in, Antoinette haar bruidsschat. Dit document zal eeuwen later worden teruggevonden.',
    'game.tt.contract.location': 'Notariaat Hallennes',
    'game.tt.contract.character': 'Notaris & getuigen',
    'game.tt.contract.choice1': 'Onderteken het contract',

    'game.tt.celebration.title': 'Het huwelijksfeest',
    'game.tt.celebration.desc': 'Het hele dorp viert mee. Er wordt gedanst en gezongen in het Picardisch dialect. De bruidegom krijgt traditionele geschenken van de dorpelingen.',
    'game.tt.celebration.location': 'Dorpsplein Hallennes',
    'game.tt.celebration.character': 'Dorpsgemeenschap',
    'game.tt.celebration.choice1': 'Begin aan het nieuwe leven',

    'game.tt.boquillon.title': 'Het Boquillon Ambacht',
    'game.tt.boquillon.desc': 'Je leert de kunst van het houthakken en houtskolenbranden. Dit is zwaar maar eerlijk werk dat al generaties lang in de familie zit.',
    'game.tt.boquillon.location': 'Bos van Haubourdin',
    'game.tt.boquillon.character': 'Vader Deleforge',
    'game.tt.boquillon.choice1': 'Vertel over de toekomstplannen',

    'game.tt.migration.title': 'De grote beslissing',
    'game.tt.migration.desc': 'Het is 1699. De oorlogen van Lodewijk XIV hebben het land verwoest. De grens is verlegd, jullie zijn nu onderdanen van de Franse koning. Velen trekken weg.',
    'game.tt.migration.location': 'Frans-Vlaanderen',
    'game.tt.migration.character': 'Familie Delforge',
    'game.tt.migration.choice1': 'Trek naar het noorden, naar Vlaanderen',
    'game.tt.migration.choice2': 'Blijf en wacht af',

    'game.tt.journey.title': 'De reis naar Izegem',
    'game.tt.journey.desc': 'Met paard en kar trek je noordwaarts, over de grens naar de Zuidelijke Nederlanden. Na een reis van enkele dagen bereik je Izegem in West-Vlaanderen.',
    'game.tt.journey.location': 'Onderweg naar Izegem',
    'game.tt.journey.character': 'Familie Delforge',
    'game.tt.journey.choice1': 'Vestig je in Izegem',

    'game.tt.stay.title': 'Moeilijke tijden',
    'game.tt.stay.desc': 'De situatie verslechtert. De belastingen zijn hoog, het werk is schaars. Steeds meer families vertrekken naar het noorden.',
    'game.tt.stay.location': 'Hallennes',
    'game.tt.stay.character': 'Familie Delforge',
    'game.tt.stay.choice1': 'Besluit alsnog te vertrekken',

    'game.tt.izegem.title': 'Aankomst in Izegem',
    'game.tt.izegem.desc': 'Izegem is een levendige stad met veel ambachtslieden. De familie integreert snel — Hubert vindt werk en de kinderen leren Nederlands.',
    'game.tt.izegem.location': 'Izegem, West-Vlaanderen',
    'game.tt.izegem.character': 'Familie Delforge',
    'game.tt.izegem.choice1': 'Ontwikkel het timmermansambacht',
    'game.tt.izegem.choice2': 'Bouw familiebanden op',

    'game.tt.craftsmanship.title': 'Generaties vakmanschap',
    'game.tt.craftsmanship.desc': 'Door de eeuwen heen evolueert het beroep: van boquillon naar timmerman, van schrijnwerker naar meubelmaker. Het werk met hout blijft in de familie.',
    'game.tt.craftsmanship.location': 'Izegem',
    'game.tt.craftsmanship.character': 'Generaties Deforce',
    'game.tt.craftsmanship.choice1': 'Spring naar 1857',

    'game.tt.integration.title': 'Nieuwe familiebanden',
    'game.tt.integration.desc': 'De kinderen trouwen met lokale families. De naam verandert langzaam: van Deleforge naar Delforche, van Deforche naar Deforce.',
    'game.tt.integration.location': 'Izegem',
    'game.tt.integration.character': 'Familie Deforce',
    'game.tt.integration.choice1': 'Spring naar 1857',

    'game.tt.charlesLouis.title': 'Charles Louis Deforce',
    'game.tt.charlesLouis.desc': 'In 1857 wordt Charles Louis geboren. Hij wordt timmerman en houtsnijder, net als zijn voorouders. Hij trouwt drie keer en krijgt vele kinderen.',
    'game.tt.charlesLouis.location': 'Izegem',
    'game.tt.charlesLouis.character': 'Charles Louis Deforce',
    'game.tt.charlesLouis.choice1': 'Reis naar het heden',

    'game.tt.modern.title': 'De familiereünie',
    'game.tt.modern.desc': 'Het is 2024. Meer dan honderd afstammelingen van Marcel Deforce en Magdalena Geldof komen samen in Laarne. De familiegeschiedenis van 340 jaar is bewaard en gedeeld.',
    'game.tt.modern.location': 'Prullenbos, Laarne',
    'game.tt.modern.character': 'Familie Deforce (2024)',

