    'banner.dismiss': 'Dismiss',

    // Hero
    'hero.subtitle': 'Some stories from',
    'hero.title1': '600 Years',
    'hero.title2': 'of Family History',
    'hero.title3': 'Deforce',
    'hero.ancestors': 'About the ancestors and descendants of',
    'hero.author': 'by Marc Deforce',
    'hero.startGames': 'Start Games',

    // Voorwoord
    'voorwoord.title': 'Foreword',
    'voorwoord.subtitle': 'Why this book?',
    'voorwoord.p1': "For more than twenty-five years, I have been researching our ancestors. On Sunday, September 29, 2024, we gathered at the Prullenbos in Laarne: one hundred and twelve descendants of Marcel Deforce and Magdalena Geldof. That day made one thing clear: it was time to bring together all my discoveries into readable stories that bring the facts to life.",
    'voorwoord.p2': "This book tells the journey of the Deleforge and Follet families, who lived around 1685 in French Walloon Flanders, through their migration to West Flanders, to their settlement in Izegem. Central to the story is Charles-Louis Deforce, my great-grandfather – the link between the distant ancestors and the generations we still knew.",
    'voorwoord.p3': "I hope this book connects you with the past and perhaps inspires your own search. This is my contribution to our family history. Now it is up to you to continue writing it.",
    'voorwoord.p4': "This book is not a complete family history. Such a project would take years and might even be impossible. It is a collection of stories – stories about the people who came before us, about their lives, their choices, their struggles, and their small victories.",
    'voorwoord.p5': "Some of these stories are well documented; others are based on fragments, interpretations, connections I have made myself. Where I doubt, I mention it. Where I am certain, I refer to the sources.",
    'voorwoord.p6': "The family tree is a living document. Each generation adds something to it. Each discovery opens new questions. And each question leads – if we are lucky – to a new story.",
    'voorwoord.p7': "In the first chapters, I go back to the earliest ancestors I could trace: the Deleforge and Follet families, who lived around 1685 in French Walloon Flanders.",
    'voorwoord.p8': "Then I follow the line through the centuries: from the founding ancestors Hubert and Antoinette to their children and grandchildren, from the migration to West Flanders to the settlement in Izegem.",
    'voorwoord.p9': "One figure is central to this story: Charles-Louis Deforce, my great-grandfather. He was hardly spoken of in the family, but his traces are everywhere: in the registers, in the photos, in the stories that were passed on.",
    'voorwoord.quote': '"It is up to future generations to continue searching: to add new data, to unearth sources, to draw connections more sharply. This is not an endpoint, but a starting point for further discoveries."',
    'voorwoord.p10': "I hope this book gives you something: a sense of connection with the past, a better understanding of where we come from, and perhaps – who knows – the impetus for your own search.",
    'voorwoord.p11': "This is my contribution to that history. Now it is up to you to continue writing it.",
    'voorwoord.author': '— Marc Deforce',
    'voorwoord.occasion': 'on the occasion of his eightieth birthday, December 2026',
