    // TimeTravel Scenes
    'game.tt.start.title': 'The beginning of a new life',
    'game.tt.start.desc': 'It is 1685 in the Weppes region near Lille. Young Hubert Deleforge, son of a boquillon (woodcutter), faces an important choice. He is engaged to Antoinette Follet, daughter of a local farmer.',
