    'game.tt.contract.choice1': 'Sign the contract',

    'game.tt.celebration.title': 'The wedding feast',
    'game.tt.celebration.desc': 'The whole village celebrates. There is dancing and singing in the Picard dialect. The groom receives traditional gifts from the villagers.',
    'game.tt.celebration.location': 'Village square Hallennes',
    'game.tt.celebration.character': 'Village community',
    'game.tt.celebration.choice1': 'Begin the new life',

    'game.tt.boquillon.title': 'The Boquillon Craft',
    'game.tt.boquillon.desc': 'You learn the art of woodcutting and charcoal burning. This is hard but honest work that has been in the family for generations.',
    'game.tt.boquillon.location': 'Haubourdin Forest',
    'game.tt.boquillon.character': 'Father Deleforge',
    'game.tt.boquillon.choice1': 'Tell about future plans',

    'game.tt.migration.title': 'The great decision',
    'game.tt.migration.desc': 'It is 1699. The wars of Louis XIV have devastated the land. The border has shifted, you are now subjects of the French king. Many are leaving.',
