    'hero.startGames': 'Iniciar Juegos',

    // Voorwoord
    'voorwoord.title': 'Prólogo',
    'voorwoord.subtitle': '¿Por qué este libro?',
    'voorwoord.p1': "Durante más de veinticinco años, he investigado sobre nuestros ancestros. El domingo 29 de septiembre de 2024, nos reunimos en el Prullenbos en Laarne: ciento doce descendientes de Marcel Deforce y Magdalena Geldof. Ese día quedó claro: era hora de reunir todos mis descubrimientos en historias legibles que dieran vida a los hechos.",
    'voorwoord.p2': "Este libro cuenta el viaje de las familias Deleforge y Follet, que vivían alrededor de 1685 en la Flandes Valona francesa, a través de su migración a Flandes Occidental, hasta su asentamiento en Izegem. Central en la historia es Charles-Louis Deforce, mi bisabuelo – el vínculo entre los ancestros lejanos y las generaciones que aún conocimos.",
    'voorwoord.p3': "Espero que este libro los conecte con el pasado y quizás inspire su propia búsqueda. Esta es mi contribución a nuestra historia familiar. Ahora les toca a ustedes seguir escribiéndola.",
    'voorwoord.p4': "Este libro no es una historia familiar completa. Tal proyecto llevaría años y quizás sería imposible. Es una colección de historias – historias sobre las personas que nos precedieron, sobre sus vidas, sus elecciones, sus luchas y sus pequeñas victorias.",
    'voorwoord.p5': "Algunas de estas historias están bien documentadas; otras se basan en fragmentos, interpretaciones, conexiones que yo mismo he establecido. Donde dudo, lo menciono. Donde tengo certeza, me refiero a las fuentes.",
    'voorwoord.p6': "El árbol genealógico es un documento vivo. Cada generación le añade algo. Cada descubrimiento abre nuevas preguntas. Y cada pregunta lleva – si tenemos suerte – a una nueva historia.",
    'voorwoord.p7': "En los primeros capítulos, vuelvo a los primeros ancestros que pude rastrear: las familias Deleforge y Follet, que vivían alrededor de 1685 en la Flandes Valona francesa.",
    'voorwoord.p8': "Luego sigo la línea a través de los siglos: desde los ancestros fundadores Hubert y Antoinette hasta sus hijos y nietos, desde la migración a Flandes Occidental hasta el asentamiento en Izegem.",
    'voorwoord.p9': "Una figura es central en esta historia: Charles-Louis Deforce, mi bisabuelo. Apenas se hablaba de él en la familia, pero sus huellas están en todas partes: en los registros, en las fotos, en las historias que sí se transmitieron.",
    'voorwoord.quote': '"Corresponde a las generaciones futuras seguir buscando: añadir nuevos datos, desenterrar fuentes, establecer conexiones más claramente. Este no es un punto final, sino un punto de partida para más descubrimientos."',
    'voorwoord.p10': "Espero que este libro les dé algo: un sentido de conexión con el pasado, una mejor comprensión de dónde venimos, y quizás – quién sabe – el impulso para su propia búsqueda.",
    'voorwoord.p11': "Esta es mi contribución a esa historia. Ahora les toca a ustedes seguir escribiéndola.",
    'voorwoord.author': '— Marc Deforce',
    'voorwoord.occasion': 'con motivo de su octogésimo cumpleaños, diciembre de 2026',
