    // Voorwoord
    'voorwoord.title': 'Avant-propos',
    'voorwoord.subtitle': 'Pourquoi ce livre ?',
    'voorwoord.p1': "Depuis plus de vingt-cinq ans, je fais des recherches sur nos ancêtres. Le dimanche 29 septembre 2024, nous nous sommes réunis au Prullenbos à Laarne : cent douze descendants de Marcel Deforce et Magdalena Geldof. Ce jour-là, une chose est devenue claire : il était temps de rassembler toutes mes découvertes en récits lisibles qui donnent vie aux faits.",
    'voorwoord.p2': "Ce livre raconte le voyage des familles Deleforge et Follet, qui vivaient vers 1685 dans la Flandre Wallonne française, à travers leur migration vers la Flandre Occidentale, jusqu'à leur installation à Izegem. Au centre de l'histoire se trouve Charles-Louis Deforce, mon arrière-grand-père – le lien entre les ancêtres lointains et les générations que nous avons encore connues.",
    'voorwoord.p3': "J'espère que ce livre vous connecte au passé et peut-être inspire votre propre recherche. Ceci est ma contribution à notre histoire familiale. Maintenant, c'est à vous de continuer à l'écrire.",
    'voorwoord.p4': "Ce livre n'est pas une histoire familiale complète. Un tel projet prendrait des années, et serait peut-être impossible. C'est une collection d'histoires – des histoires sur les personnes qui nous ont précédés, sur leur vie, leurs choix, leurs luttes et leurs petites victoires.",
    'voorwoord.p5': "Certaines de ces histoires sont bien documentées ; d'autres reposent sur des fragments, des interprétations, des liens que j'ai moi-même établis. Là où je doute, je le mentionne. Là où j'ai la certitude, je renvoie aux sources.",
    'voorwoord.p6': "L'arbre généalogique est un document vivant. Chaque génération y ajoute quelque chose. Chaque découverte ouvre de nouvelles questions. Et chaque question mène – si nous avons de la chance – à une nouvelle histoire.",
    'voorwoord.p7': "Dans les premiers chapitres, je remonte aux premiers ancêtres que j'ai pu retracer : les familles Deleforge et Follet, qui vivaient vers 1685 dans la Flandre Wallonne française.",
    'voorwoord.p8': "Ensuite, je suis la lignée à travers les siècles : des ancêtres fondateurs Hubert et Antoinette à leurs enfants et petits-enfants, de la migration vers la Flandre Occidentale à l'installation à Izegem.",
    'voorwoord.p9': "Une figure est au centre de cette histoire : Charles-Louis Deforce, mon arrière-grand-père. On parlait peu de lui dans la famille, mais ses traces sont partout : dans les registres, dans les photos, dans les histoires qui ont été transmises.",
    'voorwoord.quote': '"C\'est aux générations futures de continuer à chercher : ajouter de nouvelles données, déterrer des sources, affiner les liens. Ce n\'est pas un point final, mais un point de départ pour de nouvelles découvertes."',
    'voorwoord.p10': "J'espère que ce livre vous apportera quelque chose : un sentiment de connexion avec le passé, une meilleure compréhension d'où nous venons, et peut-être – qui sait – l'inspiration pour votre propre recherche.",
