    // TimeTravel Scenes
    'game.tt.start.title': 'Ech comminch\'mint d\'eune nouvéle vie',
    'game.tt.start.desc': 'Ch\'est 1685 dins la région des Weppes près d\'Lille. L\'jeune Hubert Deleforge, fiu d\'un boquillon (bûcheron), fait face à un choé important. Il est fiancé à Antoinette Follet, fille d\'un fermier du coin.',
    'game.tt.start.location': 'Hallennes-lez-Haubourdin',
    'game.tt.start.character': 'Hubert Deleforge',
    'game.tt.start.choice1': 'Aller chez l\'notaire pour l\'contrat d\'mariage',
    'game.tt.start.choice2': 'D\'abord visiter la forêt où travaille tin père',

    'game.tt.wedding.title': 'Les préparatifs du mariage',
    'game.tt.wedding.desc': 'L\'village est in effervescence. L\'mariage intre deux familles importantes ch\'est eune grande nouvéle. Les cloches ed l\'église Saint-Martin i vont bientôt sonner.',
    'game.tt.wedding.location': 'Hallennes-lez-Haubourdin',
    'game.tt.wedding.character': 'Hubert & Antoinette',
    'game.tt.wedding.choice1': 'Étudier l\'contrat d\'mariage',
    'game.tt.wedding.choice2': 'Participer aux festivités',

    'game.tt.forest.title': 'L\'Bos d\'Haubourdin',
    'game.tt.forest.desc': 'Dins la forêt dru, les boquillons i travaillent d\'puis des générationes. Tin père i t\'apprind les secrets du bos : quels abes i brûlent l\'mieux, comment foère du charbon.',
    'game.tt.forest.location': 'Bos d\'Haubourdin',
    'game.tt.forest.character': 'Les Boquillons',
    'game.tt.forest.choice1': 'Apprindre l\'métier d\'tin père',
    'game.tt.forest.choice2': 'R\'tourner pour les préparatifs du mariage',

    'game.tt.contract.title': 'L\'Contrat d\'Mariage',
    'game.tt.contract.desc': 'L\'notaire il lit l\'contrat : Hubert il apporte des outils agricoles et d\'l\'équipemint, Antoinette s\'dot. Ch\'document i sera r\'trouvé des siècles pus tard.',
    'game.tt.contract.location': 'Étude notariale Hallennes',
    'game.tt.contract.character': 'Notaire et témoins',
    'game.tt.contract.choice1': 'Signer l\'contrat',

    'game.tt.celebration.title': 'La fête d\'mariage',
    'game.tt.celebration.desc': 'Tout l\'village i célèbre. On danse et on chante in dialecte picard. L\'marié i reçoit des cadeaux traditionnels des villageois.',
    'game.tt.celebration.location': 'Place du village Hallennes',
    'game.tt.celebration.character': 'Communauté villageoise',
    'game.tt.celebration.choice1': 'Commincher la nouvéle vie',

    'game.tt.boquillon.title': 'L\'Métier d\'Boquillon',
    'game.tt.boquillon.desc': 'T\'apprins l\'art d\'couper du bos et d\'foère du charbon. Ch\'est un travail dur mais honnête qui est dins la famille d\'puis des générationes.',
    'game.tt.boquillon.location': 'Forêt d\'Haubourdin',
    'game.tt.boquillon.character': 'Père Deleforge',
    'game.tt.boquillon.choice1': 'Parler des projets d\'avinir',

    'game.tt.migration.title': 'La grande décision',
    'game.tt.migration.desc': 'Ch\'est 1699. Les guerres d\'Louis XIV ont dévasté l\'pays. La frontière alle a changé, vous êtes maintenant sujets du roi d\'France. Biaucoup i partent.',
    'game.tt.migration.location': 'Flandre française',
    'game.tt.migration.character': 'Famille Delforge',
    'game.tt.migration.choice1': 'Partir vers l\'nord, vers la Flandre',
    'game.tt.migration.choice2': 'Rester et attindre',

    'game.tt.journey.title': 'L\'voéyage vers Izegem',
    'game.tt.journey.desc': 'Avec ch\'val et chariot vous voéyagez vers l\'nord, traversant la frontière vers les Pays-Bas du Sud. Après plusieurs jours d\'voéyage vous arrivez à Izegem in Flandre Occidentale.',
    'game.tt.journey.location': 'In route vers Izegem',
    'game.tt.journey.character': 'Famille Delforge',
    'game.tt.journey.choice1': 'S\'installer à Izegem',

    'game.tt.stay.title': 'Temps difficiles',
    'game.tt.stay.desc': 'La situatione alle s\'aggrave. Les impôts i sont élevés, l\'travail il est rare. D\'pus in pus d\'familles i partent vers l\'nord.',
    'game.tt.stay.location': 'Hallennes',
    'game.tt.stay.character': 'Famille Delforge',
    'game.tt.stay.choice1': 'Décider finalmint d\'partir',

    'game.tt.izegem.title': 'Arrivée à Izegem',
    'game.tt.izegem.desc': 'Izegem ch\'est eune ville animée avec biaucoup d\'artisans. La famille alle s\'intègre rapidemint — Hubert il trouve du travail et les infants i apprinnent l\'néerlandais.',
    'game.tt.izegem.location': 'Izegem, Flandre Occidentale',
    'game.tt.izegem.character': 'Famille Delforge',
    'game.tt.izegem.choice1': 'Développer l\'métier d\'charpintier',
    'game.tt.izegem.choice2': 'Construire des liens familiaux',

    'game.tt.craftsmanship.title': 'Générationes d\'artisanat',
    'game.tt.craftsmanship.desc': 'À travers les siècles l\'métier il évolue : d\'boquillon à charpintier, d\'menuisier à ébéniste. L\'travail du bos il reste dins la famille.',
    'game.tt.craftsmanship.location': 'Izegem',
    'game.tt.craftsmanship.character': 'Générationes Deforce',
    'game.tt.craftsmanship.choice1': 'Sauter à 1857',

    'game.tt.integration.title': 'Nouveaux liens familiaux',
    'game.tt.integration.desc': 'Les infants i épousent des familles locales. L\'nom il change lintimint : d\'Deleforge à Delforche, d\'Deforche à Deforce.',
    'game.tt.integration.location': 'Izegem',
    'game.tt.integration.character': 'Famille Deforce',
    'game.tt.integration.choice1': 'Sauter à 1857',

    'game.tt.charlesLouis.title': 'Charles Louis Deforce',
    'game.tt.charlesLouis.desc': 'In 1857 naît Charles Louis. Il d\'vient charpintier et sculpteur sur bos, comme ses anchtres. Il s\'marie trois fois et il a biaucoup d\'infants.',
