    // Hero
    'hero.subtitle': "Quèques récits d'",
    'hero.title1': '600 Ans',
    'hero.title2': "d'Histoère Familiére",
    'hero.title3': 'Deforce',
    'hero.ancestors': 'Sus les anchtres et deschindants d',
    'hero.author': 'par Marc Deforce',
    'hero.startGames': 'Démarraches leus Jeux',

    // Voorwoord
    'voorwoord.title': 'Avent-propos',
    'voorwoord.subtitle': "Pourcoi ch'live?",
    'voorwoord.p1': "Dépis pus d'vint-chinq ans, ej fos des récherches sus nos anchtres. L'diminche 29 d'setimbe 2024, os nos sommes rassamblés au Prullenbos à Laarne : chint-douze deschindants d'Marcel Deforce et Magdalena Geldof. Ch'jour-là, eune chose est d'venue claire : il étos temps d'rassambler toutes mes découvertes in récits lisabes qu'i donnent vie aux faits.",
    'voorwoord.p2': "Ch'live raconte el voyage des familles Deleforge et Follet, qu'i vivoïent vers 1685 dins l'Flandre Wallonne française, à travers leur migration vers la Flandre Occidentale, jusqu'à leur installation à Izegem. Au mitan d'l'histoère s'trouve Charles-Louis Deforce, min arriére-grand-pére – el lin intre les anchtres lontains et les générationes qu'os avons incor connues.",
    'voorwoord.p3': "J'espére qu'ch'live vous connecte au passé et p't-ête inspire vote prope récherche. Chti ch'est m'contribution à note histoère familiére. Asteure ch'est à vous d'continuer à l'écrire.",
    'voorwoord.p4': "Ch'live n'est point eune histoère familiére complète. In tel projet pindros des années, et sros p't-ête imposibe. Ch'est eune collection d'histoères – des histoères sus les gins qu'i nous ont précédé, sus leur vie, leurs choés, leurs luttes et leurs p'tites victoires.",
    'voorwoord.p5': "Quèques-eunes éd' ches histoères sont bien documintées ; d'eutes reposent sus des fragmints, des interprétations, des lins qu'j'ai moi-méme établis. Là ù j'doute, j'el mintionne. Là ù j'ai la certitude, j'rinvoée aux sources.",
    'voorwoord.p6': "L'abe généalogique est in documint vivant. Chaque généation y ajoute quéque chose. Chaque découverte ouve éd' nouvelles questiones. Et chaque question mène – si os avons d'la chance – à eune nouvelle histoère.",
    'voorwoord.p7': "Dins les premires chapitres, j'rimonte aux premires anchtres qu'j'ai pu r'trouver : les familles Deleforge et Follet, qu'i vivoïent vers 1685 dins l'Flandre Wallonne française.",
    'voorwoord.p8': "Après, j'sus la lignée à travers les siékes : des anchtres fondateurs Hubert et Antoinette à leus éfants et p'tits-éfants, d'la migration vers la Flandre Occidentale à l'installation à Izegem.",
    'voorwoord.p9': "Eune figure est au mitan d'chte histoère : Charles-Louis Deforce, min arriére-grand-pére. On parlos peu d'lui dins la famille, mais ses traces sont partout : dins les registres, dins les fotos, dins les histoères qu'i ont été transmises.",
    'voorwoord.quote': "\"Ch'est aux générationes à v'nir d'continuer à kérquer : ajouter éd' nouvelles données, détérrer des sources, affiner les lins. Ch'n'est point in point final, mais in point d'départ pour éd' nouvelles découvertes.\"",
    'voorwoord.p10': "J'espére qu'ch'live vous apportera quéque chose : in sintimint d'connexion avec el passé, eune meyeure compréhinsion d'ù qu'os v'nons, et p't-ête – qu'sait – l'inspiration pour vote prope récherche.",
    'voorwoord.p11': "Chti ch'est m'contribution à chte histoère. Asteure ch'est à vous d'continuer à l'écrire.",
    'voorwoord.author': '— Marc Deforce',
    'voorwoord.occasion': "à l'occasion d'sin quatre-vintième anniversaire, décimbe 2026",
    'voorwoord.readMore': "Lire pus",
    'voorwoord.readLess': "Lire moins",

    // Timeline
    'timeline.title': "600 Ans d'Histoère",
