    'nav.gedcomImport': 'GEDCOM Import',
    'nav.grootouderboek': 'Großelternbuch',

    // Register Banner
    'banner.register': 'Registriere dich, um über regelmäßige Updates informiert zu bleiben!',
    'banner.registerButton': 'Jetzt registrieren',
    'banner.dismiss': 'Schließen',
    // Hero
    'hero.subtitle': 'Einige Geschichten aus',
    'hero.title1': '600 Jahre',
    'hero.title2': 'Familiengeschichte',
    'hero.title3': 'Deforce',
    'hero.ancestors': 'Über die Vorfahren und Nachkommen von',
    'hero.author': 'von Marc Deforce',
    'hero.startGames': 'Spiele starten',

    // Voorwoord
    'voorwoord.title': 'Vorwort',
    'voorwoord.subtitle': 'Warum dieses Buch?',
    'voorwoord.p1': "Seit mehr als fünfundzwanzig Jahren erforsche ich unsere Vorfahren. Am Sonntag, den 29. September 2024, trafen wir uns im Prullenbos in Laarne: hundertzwölf Nachkommen von Marcel Deforce und Magdalena Geldof. An diesem Tag wurde eines klar: Es war an der Zeit, alle meine Entdeckungen in lesbaren Geschichten zusammenzufassen, die die Fakten zum Leben erwecken.",
    'voorwoord.p2': "Dieses Buch erzählt die Reise der Familien Deleforge und Follet, die um 1685 in Französisch-Wallonisch-Flandern lebten, über ihre Migration nach Westflandern bis zu ihrer Ansiedlung in Izegem. Im Mittelpunkt steht Charles-Louis Deforce, mein Urgroßvater – die Verbindung zwischen den fernen Vorfahren und den Generationen, die wir noch kannten.",
    'voorwoord.p3': "Ich hoffe, dieses Buch verbindet Sie mit der Vergangenheit und inspiriert vielleicht zu Ihrer eigenen Suche. Dies ist mein Beitrag zu unserer Familiengeschichte. Nun liegt es an Ihnen, sie weiterzuschreiben.",
    'voorwoord.p4': "Dieses Buch ist keine vollständige Familiengeschichte. Ein solches Projekt würde Jahre dauern und wäre vielleicht unmöglich. Es ist eine Sammlung von Geschichten – Geschichten über die Menschen, die vor uns kamen, über ihr Leben, ihre Entscheidungen, ihre Kämpfe und ihre kleinen Siege.",
    'voorwoord.p5': "Einige dieser Geschichten sind gut dokumentiert; andere beruhen auf Fragmenten, Interpretationen, Verbindungen, die ich selbst hergestellt habe. Wo ich zweifle, erwähne ich das. Wo ich sicher bin, verweise ich auf die Quellen.",
    'voorwoord.p6': "Der Stammbaum ist ein lebendiges Dokument. Jede Generation fügt etwas hinzu. Jede Entdeckung öffnet neue Fragen. Und jede Frage führt – wenn wir Glück haben – zu einer neuen Geschichte.",
    'voorwoord.p7': "In den ersten Kapiteln gehe ich zurück zu den frühesten Vorfahren, die ich zurückverfolgen konnte: die Familien Deleforge und Follet, die um 1685 in Französisch-Wallonisch-Flandern lebten.",
    'voorwoord.p8': "Dann folge ich der Linie durch die Jahrhunderte: von den Stammvätern Hubert und Antoinette zu ihren Kindern und Enkeln, von der Migration nach Westflandern bis zur Ansiedlung in Izegem.",
    'voorwoord.p9': "Eine Figur steht im Mittelpunkt dieser Geschichte: Charles-Louis Deforce, mein Urgroßvater. In der Familie wurde kaum über ihn gesprochen, aber seine Spuren sind überall: in den Registern, auf den Fotos, in den Geschichten, die weitergegeben wurden.",
    'voorwoord.quote': '"Es liegt an den kommenden Generationen, weiter zu suchen: neue Daten hinzuzufügen, Quellen auszugraben, Verbindungen schärfer zu ziehen. Dies ist kein Endpunkt, sondern ein Ausgangspunkt für weitere Entdeckungen."',
    'voorwoord.p10': "Ich hoffe, dieses Buch gibt Ihnen etwas: ein Gefühl der Verbundenheit mit der Vergangenheit, ein besseres Verständnis dafür, woher wir kommen, und vielleicht – wer weiß – den Anstoß zu Ihrer eigenen Suche.",
    'voorwoord.p11': "Dies ist mein Beitrag zu dieser Geschichte. Nun liegt es an Ihnen, sie weiterzuschreiben.",
    'voorwoord.author': '— Marc Deforce',
    'voorwoord.occasion': 'anlässlich seines achtzigsten Geburtstags, Dezember 2026',
    'voorwoord.readMore': 'Weiterlesen',
    'voorwoord.readLess': 'Weniger lesen',

    // Timeline
    'timeline.title': '600 Jahre Geschichte',
    'timeline.subtitle': 'Eine Zeitleiste unserer Familiengeschichte, von den frühesten dokumentierten Vorfahren bis heute.',

    // Zoektocht
    'zoektocht.title': 'Die Suche nach unseren Vorfahren',
    'zoektocht.subtitle': 'Das große Rätsel: drei Familienzweige ohne klare Verbindung',
    'zoektocht.eureka': 'Eureka!',
    'zoektocht.lineage': 'Die direkte väterliche Linie',

    // Naamgeschiedenis
    'naam.title': 'Von Deleforge zu Deforce',
    'naam.subtitle': 'Die Entwicklung unseres Familiennamens durch die Jahrhunderte',
    'naam.herkomst': 'Herkunft und Bedeutung',
