    // TimeTravel Scenes
    'game.tt.start.title': 'Der Beginn eines neuen Lebens',
    'game.tt.start.desc': 'Es ist 1685 in der Weppes-Region bei Lille. Der junge Hubert Deleforge, Sohn eines Boquillons (Holzfäller), steht vor einer wichtigen Entscheidung. Er ist mit Antoinette Follet verlobt, Tochter eines örtlichen Pächters.',
    'game.tt.start.location': 'Hallennes-lez-Haubourdin',
    'game.tt.start.character': 'Hubert Deleforge',
    'game.tt.start.choice1': 'Geh zum Notar für den Ehevertrag',
    'game.tt.start.choice2': 'Besuche zuerst den Wald, wo dein Vater arbeitet',

    'game.tt.wedding.title': 'Die Hochzeitsvorbereitungen',
    'game.tt.wedding.desc': 'Das Dorf ist in Aufruhr. Die Hochzeit zwischen zwei angesehenen Familien ist große Neuigkeit. Die Glocken der St.-Martins-Kirche werden bald läuten.',
    'game.tt.wedding.location': 'Hallennes-lez-Haubourdin',
    'game.tt.wedding.character': 'Hubert & Antoinette',
    'game.tt.wedding.choice1': 'Studiere den Ehevertrag',
    'game.tt.wedding.choice2': 'Nimm an den Feierlichkeiten teil',

    'game.tt.forest.title': 'Der Bois d\'Haubourdin',
    'game.tt.forest.desc': 'Im dichten Wald arbeiten die Boquillons seit Generationen. Dein Vater lehrt dich die Geheimnisse des Holzes: welche Bäume am besten brennen, wie man Holzkohle herstellt.',
    'game.tt.forest.location': 'Bois d\'Haubourdin',
    'game.tt.forest.character': 'Die Boquillons',
    'game.tt.forest.choice1': 'Lerne das Handwerk deines Vaters',
    'game.tt.forest.choice2': 'Kehre für die Hochzeitsvorbereitungen zurück',

    'game.tt.contract.title': 'Der Ehevertrag',
    'game.tt.contract.desc': 'Der Notar liest den Vertrag vor: Hubert bringt landwirtschaftliche Geräte und Werkzeuge ein, Antoinette ihre Mitgift. Dieses Dokument wird Jahrhunderte später wiedergefunden.',
    'game.tt.contract.location': 'Notariat Hallennes',
    'game.tt.contract.character': 'Notar & Zeugen',
    'game.tt.contract.choice1': 'Unterschreibe den Vertrag',

    'game.tt.celebration.title': 'Das Hochzeitsfest',
    'game.tt.celebration.desc': 'Das ganze Dorf feiert mit. Es wird getanzt und im pikardischen Dialekt gesungen. Der Bräutigam erhält traditionelle Geschenke von den Dorfbewohnern.',
    'game.tt.celebration.location': 'Dorfplatz Hallennes',
    'game.tt.celebration.character': 'Dorfgemeinschaft',
    'game.tt.celebration.choice1': 'Beginne das neue Leben',

    'game.tt.boquillon.title': 'Das Boquillon-Handwerk',
    'game.tt.boquillon.desc': 'Du lernst die Kunst des Holzfällens und Kohlebrennens. Das ist harte, aber ehrliche Arbeit, die seit Generationen in der Familie liegt.',
    'game.tt.boquillon.location': 'Wald von Haubourdin',
    'game.tt.boquillon.character': 'Vater Deleforge',
    'game.tt.boquillon.choice1': 'Erzähle von den Zukunftsplänen',

    'game.tt.migration.title': 'Die große Entscheidung',
    'game.tt.migration.desc': 'Es ist 1699. Die Kriege Ludwigs XIV. haben das Land verwüstet. Die Grenze hat sich verschoben, ihr seid jetzt Untertanen des französischen Königs. Viele ziehen weg.',
    'game.tt.migration.location': 'Französisch-Flandern',
    'game.tt.migration.character': 'Familie Delforge',
    'game.tt.migration.choice1': 'Zieh nach Norden, nach Flandern',
    'game.tt.migration.choice2': 'Bleib und warte ab',

    'game.tt.journey.title': 'Die Reise nach Izegem',
    'game.tt.journey.desc': 'Mit Pferd und Wagen zieht ihr nach Norden, über die Grenze in die Südlichen Niederlande. Nach einer mehrtägigen Reise erreicht ihr Izegem in Westflandern.',
    'game.tt.journey.location': 'Unterwegs nach Izegem',
    'game.tt.journey.character': 'Familie Delforge',
    'game.tt.journey.choice1': 'Lass dich in Izegem nieder',

    'game.tt.stay.title': 'Schwere Zeiten',
    'game.tt.stay.desc': 'Die Lage verschlechtert sich. Die Steuern sind hoch, die Arbeit ist knapp. Immer mehr Familien ziehen in den Norden.',
    'game.tt.stay.location': 'Hallennes',
    'game.tt.stay.character': 'Familie Delforge',
    'game.tt.stay.choice1': 'Beschließe doch noch zu gehen',

    'game.tt.izegem.title': 'Ankunft in Izegem',
    'game.tt.izegem.desc': 'Izegem ist eine lebhafte Stadt mit vielen Handwerkern. Die Familie integriert sich schnell — Hubert findet Arbeit und die Kinder lernen Niederländisch.',
    'game.tt.izegem.location': 'Izegem, Westflandern',
    'game.tt.izegem.character': 'Familie Delforge',
    'game.tt.izegem.choice1': 'Entwickle das Zimmerhandwerk',
    'game.tt.izegem.choice2': 'Baue Familienbande auf',

    'game.tt.craftsmanship.title': 'Generationen von Handwerk',
    'game.tt.craftsmanship.desc': 'Durch die Jahrhunderte entwickelt sich der Beruf: vom Boquillon zum Zimmermann, vom Schreiner zum Möbelmacher. Die Arbeit mit Holz bleibt in der Familie.',
    'game.tt.craftsmanship.location': 'Izegem',
    'game.tt.craftsmanship.character': 'Generationen Deforce',
    'game.tt.craftsmanship.choice1': 'Springe zu 1857',

    'game.tt.integration.title': 'Neue Familienbande',
    'game.tt.integration.desc': 'Die Kinder heiraten in lokale Familien ein. Der Name ändert sich langsam: von Deleforge zu Delforche, von Deforche zu Deforce.',
    'game.tt.integration.location': 'Izegem',
    'game.tt.integration.character': 'Familie Deforce',
    'game.tt.integration.choice1': 'Springe zu 1857',

    'game.tt.charlesLouis.title': 'Charles Louis Deforce',
