    // TimeTravel Scenes
    'game.tt.start.title': 'T begin van e nieuw leven',
    'game.tt.start.desc': 'T is 1685 in de Weppes-streek by Rysel. De jonge Hubert Deleforge, zône van e boquillon (houtakker), stoat vôor e belangrijke keuze. Hy is verloofd me Antoinette Follet, dochter van e lokale pachter.',
    'game.tt.start.location': 'Hallennes-lez-Haubourdin',
    'game.tt.start.character': 'Hubert Deleforge',
    'game.tt.start.choice1': 'Goan noar de notaris vôor t huwelieksoakte',
    'game.tt.start.choice2': 'Eerst t bos bezoekn woar je voader werkt',

    'game.tt.wedding.title': 'De huwelieksvôorbereidingen',
    'game.tt.wedding.desc': 'T dôrp is in rep en roer. T huweliek tusschen twee vôoroanstoandn familles is grôot nieuws. De klokken van de Sint-Martinuskerke goan spoedig luudn.',
    'game.tt.wedding.location': 'Hallennes-lez-Haubourdin',
    'game.tt.wedding.character': 'Hubert & Antoinette',
    'game.tt.wedding.choice1': 'T huwelieksoakte bestuderen',
    'game.tt.wedding.choice2': 'Deelneemn an de feestelijkheden',

    'game.tt.forest.title': 'T Bos d\'Haubourdin',
    'game.tt.forest.desc': 'In t dichte bos werkn de boquillons al generaties lange. Je voader leert je de geheiemn van t hout: welke bôomn t beste brandn, hoe je houtskôole moakt.',
    'game.tt.forest.location': 'Bos d\'Haubourdin',
    'game.tt.forest.character': 'De Boquillons',
    'game.tt.forest.choice1': 'T ambacht van je voader leren',
    'game.tt.forest.choice2': 'Weerkoamn vôor de huwelieksvôorbereidingn',

    'game.tt.contract.title': 'T Huwelieksoakte',
    'game.tt.contract.desc': 'De notaris leest t oakte vôor: Hubert bringt landbouwgerief en werktuugn in, Antoinette hoar bruudsschat. Dit document goat eeuwn loater weergevondn wordn.',
    'game.tt.contract.location': 'Notariaat Hallennes',
    'game.tt.contract.character': 'Notaris & getuugn',
    'game.tt.contract.choice1': 'T oakte tekeenn',

    'game.tt.celebration.title': 'T huwelieksfestn',
    'game.tt.celebration.desc': 'T héele dôrp viert mee. Der wordt gedanst en gezungn in t Picardisch dialect. De bruidegom krygt traditionele geschenken van de dôrpelingn.',
    'game.tt.celebration.location': 'Dôrpsplein Hallennes',
    'game.tt.celebration.character': 'Dôrpsgemeenschap',
    'game.tt.celebration.choice1': 'Beginn an t nieuw leven',

    'game.tt.boquillon.title': 'T Boquillon Ambacht',
    'game.tt.boquillon.desc': 'Je leert de kunst van t houtakkn en houtskolnbrandn. Dit is zwoar moar eerlik werk da al generaties lange in de familie zit.',
    'game.tt.boquillon.location': 'Bos van Haubourdin',
    'game.tt.boquillon.character': 'Voader Deleforge',
    'game.tt.boquillon.choice1': 'Verteln over de toekomstplannn',

    'game.tt.migration.title': 'De grôote beslissinge',
    'game.tt.migration.desc': 'T is 1699. De ôorlogn van Lodewiek XIV ebn t land verwôest. De grenze is verleid, gunder zyt nu onderdoandn van de Franse kônink. Vele trekkn weg.',
    'game.tt.migration.location': 'Frans-Vloandern',
    'game.tt.migration.character': 'Familie Delforge',
    'game.tt.migration.choice1': 'Trekkn noar t noôrdn, noar Vloandern',
    'game.tt.migration.choice2': 'Blyvn en wachtn',

    'game.tt.journey.title': 'De reis noar Izegem',
    'game.tt.journey.desc': 'Me péerd en karre trekk je noôrdwoarts, over de grenze noar de Zuudelike Nederlandn. Noa e reis van enkelen doagn bereik je Izegem in West-Vloandern.',
    'game.tt.journey.location': 'Onderweg noar Izegem',
    'game.tt.journey.character': 'Familie Delforge',
    'game.tt.journey.choice1': 'Je vestign in Izegem',

    'game.tt.stay.title': 'Môeilike tiedn',
    'game.tt.stay.desc': 'De situoasje verslechtert. De belastingn zyn hôog, t werk is schors. Stees mee familles vertrekkn noar t noôrdn.',
    'game.tt.stay.location': 'Hallennes',
    'game.tt.stay.character': 'Familie Delforge',
    'game.tt.stay.choice1': 'Besluutn toch nog te vertrekkn',

    'game.tt.izegem.title': 'Oankomste in Izegem',
    'game.tt.izegem.desc': 'Izegem is e levendige stad me vele ambachtsliedn. De familie integreert snel — Hubert vindt werk en de kindern leren Nederlands.',
    'game.tt.izegem.location': 'Izegem, West-Vloandern',
