    'game.tt.izegem.choice1': 'T timmermansambacht ontwikkeln',
    'game.tt.izegem.choice2': 'Familiebanden opbouwn',

    'game.tt.craftsmanship.title': 'Generaties vakmanschap',
    'game.tt.craftsmanship.desc': 'Deur de eeuwn heen evolueert t beroep: van boquillon noar timmerman, van schrynwerker noar meubelmoaker. T werk me hout blyft in de familie.',
    'game.tt.craftsmanship.location': 'Izegem',
