    // Hero
    'hero.subtitle': 'Enkele verhoalen uut',
    'hero.title1': '600 Joar',
    'hero.title2': 'Familiegeschiedenisse',
    'hero.title3': 'Deforce',
    'hero.ancestors': 'Over de vôorouders en noazoaten van',
    'hero.author': 'deur Marc Deforce',
    'hero.startGames': 'Start de Speln',

    // Voorwoord
    'voorwoord.title': 'Vôorwoord',
    'voorwoord.subtitle': 'Woarom dit boek?',
    'voorwoord.p1': "Ol mee dan vyfentwintig joar doe ik opzoekingen noar uuze vôorouders. Op zondag 29 september 2024 kwoamen we soamen in Het Prullenbos in Laarne: honderdtwoalf ofstammelingen van Marcel Deforce en Magdalena Geldof. Die dag moakte ene ding dudelik: t was tied om ol myn ontdekkingen soamen te brengen in leesboare verhoalen die de feiten tot leven brengen.",
    'voorwoord.p2': "Dit boek fertelt de reis van de families Deleforge en Follet, die rond 1685 in Frans Woals-Vloanderen leefden, via ulder migroasje noar West-Vloanderen, tot an ulder vestiging in Izegem. Centroal stoat Charles-Louis Deforce, myn overgrôotvader – de schoakel tussen de verre vôorouders en de generoasjes die me nog gekend ebn.",
    'voorwoord.p3': "Ik hope dat dit boek ulder verbindt mee t verleeden en mesjiens de oanzet geeft tot e eigen zoektocht. Dit is myn bydroage an uuze familiegeschiedenisse. Nu is t an ulder om ze verder te schryven.",
    'voorwoord.p4': "Dit boek is geen volledige familiegeschiedenisse. Zô'n project zou joaren vergen, en mesjiens wel onmogeliek zyn. T is e verzoameling verhoalen – verhoalen over de mensen die ons vôorofgingen, over ulder leevn, ulder keuzes, ulder worstelingen en ulder kleine overwinningen.",
    'voorwoord.p5': "Sommige van deze verhoalen zyn goed gedokementeerd; andere berusten op fragmènten, op interpretoasjes, op verbanden die k zelf gelegd ebbe. Woar da k twyfele, vermelde k dat. Woar da k zekerheid ebbe, verwys ik noar de bronnen.",
    'voorwoord.p6': "De stamboom is e levend dokement. Elke generoasje voegt er iets an toe. Elke ontdekking opent nieuwe vroagen. En elke vroage leidt – ols we geluk ebn – noar e nieuw verhoal.",
    'voorwoord.p7': "In de eerste hoofdstukken go ik were noar de vroegste vôorouders die k kusse troaceren: de families Deleforge en Follet, die rond 1685 in t Franse Woals-Vloanderen leefden.",
    'voorwoord.p8': "Daarnoa volge k de lien deur de eeuwen heen: van de stamouders Hubert en Antoinette noar ulder kinders en kleinkinders, van de migroasje noar West-Vloanderen noar de vestiging in Izegem.",
    'voorwoord.p9': "Ene figuur stoat centroal in dit verhoal: Charles-Louis Deforce, myn overgrôotvader. Over hem wierd in de familie nauwelikse gesproken, mor zyn sporen liggen ovendal: in de registers, in de foto's, in de verhoalen die wé wierden deurgeferteld.",
    'voorwoord.quote': '"T is an de kommende generoasjes om verder te zoeken: nieuwe gegevens toe te voegen, bronnen op te diepen, verbanden scherper te trekken. Dit is geen eindpunt, mor e stortpunt vôor verdere ontdekkingen."',
    'voorwoord.p10': "Ik hope dat dit boek ulder iets geeft: e gevoel van verbondenheid mee t verleeden, e beter begryp van woar da me vandoan kommen, en mesjiens – wie weet – de oanzet tot e eigen zoektocht.",
    'voorwoord.p11': "Dit is myn bydroage an die geschiedenisse. Nu is t an ulder om ze verder te schryven.",
    'voorwoord.author': '— Marc Deforce',
    'voorwoord.occasion': "ter gelegenheid van zyn tachtigste verjoardag, december 2026",
    'voorwoord.readMore': 'Lees mee',
    'voorwoord.readLess': 'Lees minder',

