    // Register Banner
    'banner.register': 'Registrera dig för att hålla dig uppdaterad om regelbundna uppdateringar!',
    'banner.registerButton': 'Registrera nu',
    'banner.dismiss': 'Stäng',

    // Hero
    'hero.subtitle': 'Några berättelser från',
    'hero.title1': '600 År',
    'hero.title2': 'Familjehistoria',
    'hero.title3': 'Deforce',
    'hero.ancestors': 'Om förfäderna och ättlingarna till',
    'hero.author': 'av Marc Deforce',
    'hero.startGames': 'Starta Spelen',

    // Voorwoord
    'voorwoord.title': 'Förord',
    'voorwoord.subtitle': 'Varför denna bok?',
    'voorwoord.p1': "I mer än tjugofem år har jag forskat om våra förfäder. Söndagen den 29 september 2024 samlades vi i Prullenbos i Laarne: etthundratolv ättlingar till Marcel Deforce och Magdalena Geldof. Den dagen blev en sak tydlig: det var dags att samla alla mina upptäckter i läsbara berättelser som ger liv åt fakta.",
    'voorwoord.p2': "Denna bok berättar resan för familjerna Deleforge och Follet, som levde i franska Vallonsk-Flandern omkring 1685, via deras migration till Västflandern, fram till deras bosättning i Izegem. I centrum står Charles-Louis Deforce, min farfars far – länken mellan de avlägsna förfäderna och de generationer vi själva har känt.",
    'voorwoord.p3': "Jag hoppas att denna bok förbinder er med det förflutna och kanske inspirerar till en egen sökresa. Detta är mitt bidrag till vår familjehistoria. Nu är det er tur att skriva vidare.",
    'voorwoord.p4': "Denna bok är ingen fullständig familjehistoria. Ett sådant projekt skulle ta år, och kanske vara omöjligt. Det är en samling berättelser – berättelser om människorna som kom före oss, om deras liv, deras val, deras kamper och deras små segrar.",
    'voorwoord.p5': "Några av dessa berättelser är väl dokumenterade; andra bygger på fragment, på tolkningar, på kopplingar som jag själv har gjort. Där jag tvivlar, nämner jag det. Där jag är säker, hänvisar jag till källorna.",
    'voorwoord.p6': "Släktträdet är ett levande dokument. Varje generation lägger till något. Varje upptäckt öppnar nya frågor. Och varje fråga leder – om vi har tur – till en ny berättelse.",
    'voorwoord.p7': "I de första kapitlen går jag tillbaka till de tidigaste förfäderna jag kunde spåra: familjerna Deleforge och Follet, som levde i franska Vallonsk-Flandern omkring 1685.",
    'voorwoord.p8': "Sedan följer jag linjen genom århundradena: från stamföräldrarna Hubert och Antoinette till deras barn och barnbarn, från migrationen till Västflandern till bosättningen i Izegem.",
    'voorwoord.p9': "En person står i centrum av denna berättelse: Charles-Louis Deforce, min farfars far. Om honom talades knappt i familjen, men hans spår finns överallt: i registren, i fotografierna, i berättelserna som faktiskt berättades vidare.",
    'voorwoord.quote': '"Det är de kommande generationernas uppgift att fortsätta söka: lägga till nya data, gräva fram källor, dra tydligare kopplingar. Detta är ingen slutpunkt, utan en startpunkt för vidare upptäckter."',
    'voorwoord.p10': "Jag hoppas att denna bok ger er något: en känsla av samhörighet med det förflutna, en bättre förståelse för var vi kommer ifrån, och kanske – vem vet – inspiration till en egen sökresa.",
    'voorwoord.p11': "Detta är mitt bidrag till den historien. Nu är det er tur att skriva vidare.",
    'voorwoord.author': '— Marc Deforce',
    'voorwoord.occasion': 'i samband med sin åttionde födelsedag, december 2026',
    'voorwoord.readMore': 'Läs mer',
    'voorwoord.readLess': 'Läs mindre',

